import{_ as t,o as e,c as s,a5 as i}from"./chunks/framework.BZzouRtU.js";const o="/study/images/math/comparison-tolerances.svg",r="/study/images/math/comparison-pitfalls.svg",b=JSON.parse('{"title":"浮動小数点の比較と誤差の扱い — 絶対許容差・相対許容差を決める","description":"","frontmatter":{"title":"浮動小数点の比較と誤差の扱い — 絶対許容差・相対許容差を決める","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"math","summary":"厳密な等値と近似一致の目的を分け、絶対許容差と相対許容差を単位・値域・用途から決める。binary32入力用の比較方針、NaNや無限大、非推移性、到達判定、保存時に失う情報も扱う。","aliases":["floating point comparison","浮動小数点比較","近似一致","approximate equality","absolute tolerance","絶対許容差","relative tolerance","相対許容差","epsilon","Single.Epsilon","NaN","非推移性","ヒステリシス"],"verification":"一次資料照合（2026-11-03）"}},"headers":[],"relativePath":"math/floating-point-comparison.md","filePath":"math/floating-point-comparison.md"}'),n={name:"math/floating-point-comparison.md"};function l(d,a,p,h,c,k){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="浮動小数点の比較と誤差の扱い-—-絶対許容差・相対許容差を決める" tabindex="-1">浮動小数点の比較と誤差の扱い — 絶対許容差・相対許容差を決める <a class="header-anchor" href="#浮動小数点の比較と誤差の扱い-—-絶対許容差・相対許容差を決める" aria-label="Permalink to &quot;浮動小数点の比較と誤差の扱い — 絶対許容差・相対許容差を決める&quot;">​</a></h1><p>浮動小数点の値を比べる前に、<strong>同じ数値であることを調べるのか、この用途で十分近いことを調べるのか</strong>を決めます。近似一致は、許した差の範囲に入るという判定です。計算が数学的に正しいことや、ゲームの物理状態が正しいことまで保証する機能ではありません。</p><p>この記事はC++20を基準に、<strong>binary32の<code>float</code>入力を、binary64の<code>double</code>で比較する教材の方針</strong>を示します。型名だけでこれらの形式が保証されるわけではありません。表せる値、丸め、刻み幅と環境の確認方法は<a href="/study/data/floating-point-spacing.html">floatの表現と刻み幅</a>へ委ねます。</p><h2 id="厳密な等値を使う場面" tabindex="-1">厳密な等値を使う場面 <a class="header-anchor" href="#厳密な等値を使う場面" aria-label="Permalink to &quot;厳密な等値を使う場面&quot;">​</a></h2><p><code>a == b</code>は、比較に必要な型変換を行った後の値が等しいかを調べます。例えば、有限値をそのままコピーした結果や、プログラムが明示的に代入した<code>0.0f</code>、目標値を代入して完了させた状態を確認したい場合には、厳密な等値が目的に合います。「浮動小数点だから常に<code>==</code>を禁止する」という規則にはしません。<a href="https://timsong-cpp.github.io/cppwp/n4861/expr.eq" target="_blank" rel="noreferrer">C++20草案N4861: expr.eq</a></p><p>一方、異なる計算経路の結果を比べたり、測定や近似計算の結果を期待値と比べたりするときは、完全な一致を要求する理由があるかを確認します。表示が同じでも内部の値が同じとは限らず、逆に、丸めによって元は異なる値が同じ保存値になる場合もあります。</p><p>また、IEEE形式の<code>==</code>は、ビット列の同一性を調べる操作でもありません。＋0と−0は等しく、NaNは自分自身とも等しくありません。これらの値を使うなら、特殊値をどう扱うかも比較の仕様に含めます。<a href="https://learn.microsoft.com/en-us/cpp/build/reference/fp-specify-floating-point-behavior?view=msvc-170" target="_blank" rel="noreferrer">Microsoft: /fp — special values</a></p><h2 id="許容差は、用途ごとに決める予算" tabindex="-1">許容差は、用途ごとに決める予算 <a class="header-anchor" href="#許容差は、用途ごとに決める予算" aria-label="Permalink to &quot;許容差は、用途ごとに決める予算&quot;">​</a></h2><p>許容差（tolerance）は、近似一致と判定するために許す差の上限です。次の三つを区別します。</p><table tabindex="0"><thead><tr><th>調べたいもの</th><th>意味</th></tr></thead><tbody><tr><td>比較の許容差</td><td>二つの保存値の差を、どこまで受け入れるか</td></tr><tr><td>演算誤差の上限</td><td>入力や計算手順を分析し、真の値とのずれをどこまで保証できるか</td></tr><tr><td>物理・製品上の要求</td><td>到着半径、測定精度、画面上で許すずれなどの仕様</td></tr></tbody></table><p>許容差を大きくして判定が通っても、誤差の原因を除いたことにはなりません。分析や計測から比較の予算を決めることはできますが、<strong>近いと判定された事実だけから、演算誤差の上限を逆に証明することはできません。</strong></p><h2 id="絶対許容差と相対許容差" tabindex="-1">絶対許容差と相対許容差 <a class="header-anchor" href="#絶対許容差と相対許容差" aria-label="Permalink to &quot;絶対許容差と相対許容差&quot;">​</a></h2><p>二つの有限値をa、bとし、差を<code>diff = |a − b|</code>とします。</p><table tabindex="0"><thead><tr><th>許容差</th><th>判定</th><th>単位と役割</th></tr></thead><tbody><tr><td>絶対許容差<code>absTol</code></td><td><code>diff ≤ absTol</code></td><td>a、bと同じ単位。何m、何秒までという予算</td></tr><tr><td>相対許容差<code>relTol</code></td><td><code>diff ≤ relTol × max(abs(a), abs(b))</code></td><td><code>relTol</code>は無次元の比率。値の大きさに応じた予算</td></tr></tbody></table><p>絶対許容差は、値が大きくても小さくても同じ量です。説明用に<code>absTol = 0.25</code>、1unit＝1mとすると、0mと0.125mは受け入れ、0mと0.5mは受け入れません。この0.25mを、すべてのゲームで使う推奨値にはしません。</p><p>相対許容差では、双方の絶対値の大きい方を基準にします。説明用の<code>relTol = 1/1024</code>は約0.0977%です。a＝1024、b＝1025なら、差は1、基準は1025、許す差は<code>1025/1024 = 1.0009765625</code>なので受け入れます。aとbを入れ替えても同じ判定になる、対称な基準です。</p><h3 id="組み合わせるときはorとして読む" tabindex="-1">組み合わせるときはORとして読む <a class="header-anchor" href="#組み合わせるときはorとして読む" aria-label="Permalink to &quot;組み合わせるときはORとして読む&quot;">​</a></h3><p>本教材では、絶対許容差と相対許容差を次のように組み合わせます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>diff  = |a − b|</span></span>
<span class="line"><span>scale = max(|a|, |b|)</span></span>
<span class="line"><span>limit = max(absTol, relTol × scale)</span></span>
<span class="line"><span>近似一致: diff ≤ limit</span></span></code></pre></div><p><code>max</code>を使うので、これは<strong>絶対条件または相対条件のどちらかを満たせば受け入れるOR判定</strong>です。両方を同時に満たす必要はありません。この対称な組合せはPEP 485でも説明されています。本記事の入力型や許容差の制限、実装条件は後述する教材独自の契約です。<a href="https://peps.python.org/pep-0485/" target="_blank" rel="noreferrer">PEP 485: Proposed Implementation</a></p><figure class="study-figure"><img src="`+o+`" alt="絶対許容差0.25で0と0.125を受け入れ、0と0.5を受け入れない例。相対許容差1/1024では1024と1025を受け入れるが、0と0.125は受け入れない。二つの条件をmaxで組み合わせるとOR判定になる。" width="760" height="1510"><figcaption><strong>絶対許容差は同じ量、相対許容差は値の尺度に応じた量。</strong> 数値は仕組みを示す例で、実製品の推奨値ではありません。<a href="/study/images/math/comparison-tolerances.svg" target="_blank" rel="noopener noreferrer">二つの許容差の図を拡大</a></figcaption></figure><h3 id="ゼロ付近で相対条件だけでは足りない理由" tabindex="-1">ゼロ付近で相対条件だけでは足りない理由 <a class="header-anchor" href="#ゼロ付近で相対条件だけでは足りない理由" aria-label="Permalink to &quot;ゼロ付近で相対条件だけでは足りない理由&quot;">​</a></h3><p>a＝0、b＝0.125の場合、相対許容差1/1024で許す差は<code>0.125/1024 = 0.0001220703125</code>です。実際の差0.125には届きません。0と非ゼロの値を比べると、差と基準の大きさが同じになるため、<code>relTol &lt; 1</code>の相対条件だけでは受け入れられません。ゼロ付近をどこまで受け入れるかは、同じ単位の絶対予算で決めます。<a href="https://peps.python.org/pep-0485/" target="_blank" rel="noreferrer">PEP 485: Behavior near zero</a></p><p>反対に、絶対予算だけなら大きな値でも許す差は変わりません。<code>absTol = 0.25</code>では1024と1025の差1を受け入れませんが、上の相対条件では受け入れます。二つを組み合わせる理由は、このような目的の違いにあります。</p><h2 id="本教材の比較関数の契約" tabindex="-1">本教材の比較関数の契約 <a class="header-anchor" href="#本教材の比較関数の契約" aria-label="Permalink to &quot;本教材の比較関数の契約&quot;">​</a></h2><p>対象はbinary32の<code>float</code>入力二つです。許容差は<code>double</code>として受け取り、計算側もbinary64の<code>double</code>で行います。<strong>任意の<code>double</code>入力まで扱う万能な比較関数という契約ではありません。</strong></p><table tabindex="0"><thead><tr><th>処理する順序</th><th>方針</th></tr></thead><tbody><tr><td>1. 許容差の検査</td><td><code>absTol</code>は有限かつ0以上。<code>relTol</code>は有限かつ0以上1未満。違反は例外</td></tr><tr><td>2. NaN</td><td>a、bのどちらかがNaNなら<code>false</code></td></tr><tr><td>3. 厳密な等値</td><td><code>a == b</code>なら<code>true</code>。＋0と−0、同符号の無限大も含む</td></tr><tr><td>4. 残る非有限値</td><td>無限大と有限値、異符号の無限大などは<code>false</code></td></tr><tr><td>5. 有限値の計算</td><td>先に<code>double</code>へ拡張し、上の<code>diff ≤ limit</code>を評価</td></tr></tbody></table><p>相対許容差を1未満にするのは、教材での意図を明確にするための選択です。一般の数値ライブラリがすべて同じ契約を採るわけではありません。許容差の検査を先に行うため、<strong>aとbが同じ値でも、不正な許容差を渡せば例外</strong>になります。</p><p>NaNは計算不成立などを示し得る値なので、今回の「近い」に含めません。同符号の無限大を受け入れるのは、等値の分岐を含めるという今回の方針です。すべての計測や物理判定で無限大を受け入れてよいという意味ではなく、有限入力を必須にする用途なら、その要件を別に検査します。<code>std::isfinite</code>は有限値と無限大・NaNを区別するAPIです。<a href="https://learn.microsoft.com/en-us/cpp/c-runtime-library/reference/finite-finitef?view=msvc-170" target="_blank" rel="noreferrer">Microsoft: isfinite</a></p><h3 id="差を計算する前にdoubleへ拡張する" tabindex="-1">差を計算する前にdoubleへ拡張する <a class="header-anchor" href="#差を計算する前にdoubleへ拡張する" aria-label="Permalink to &quot;差を計算する前にdoubleへ拡張する&quot;">​</a></h3><p>次は、許容差と特殊値の検査が済んだ後の計算部分です。<code>&lt;algorithm&gt;</code>と<code>&lt;cmath&gt;</code>を使い、a、bは<code>float</code>、許容差は<code>double</code>とします。</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> da </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static_cast&lt;double&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(a);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static_cast&lt;double&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(b);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> diff </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fabs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(da </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> scale </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fabs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(da), </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fabs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(db));</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> close </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> diff </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(absTol, relTol </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> scale);</span></span></code></pre></div><p><code>float</code>から<code>double</code>への昇格は値を保存します。binary32の有限値二つの差はbinary64の値域に収まるので、<strong><code>float</code>のまま差を求める際のオーバーフローを避けられます</strong>。<code>static_cast&lt;double&gt;(a - b)</code>では引き算を先に<code>float</code>で行うため、この目的を満たしません。<a href="https://timsong-cpp.github.io/cppwp/n4861/conv.fpprom" target="_blank" rel="noreferrer">N4861: conv.fpprom</a>、<a href="https://learn.microsoft.com/en-us/cpp/build/ieee-floating-point-representation?view=msvc-170" target="_blank" rel="noreferrer">Microsoft: IEEE Floating-Point Representation</a></p><p>ただし、その後の差や積が数学的な実数として常に厳密になるという意味ではありません。判定の境界にも<code>double</code>の丸めが関わります。C++20の型名だけからbinary32／binary64だと決めず、実践記事では型の性質と実行条件を確認します。</p><h2 id="epsilonという名前だけで許容差を決めない" tabindex="-1">epsilonという名前だけで許容差を決めない <a class="header-anchor" href="#epsilonという名前だけで許容差を決めない" aria-label="Permalink to &quot;epsilonという名前だけで許容差を決めない&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名前</th><th>意味</th><th>binary32での値</th></tr></thead><tbody><tr><td>C++の<code>numeric_limits&lt;float&gt;::epsilon()</code></td><td>1と、1より大きい最小の表現可能値との差</td><td>2⁻²³、約1.19×10⁻⁷</td></tr><tr><td>C#の<code>Single.Epsilon</code>／<code>float.Epsilon</code></td><td>最小の正の<code>Single</code>値</td><td>subnormalを保持する通常の条件で2⁻¹⁴⁹、約1.40×10⁻⁴⁵</td></tr></tbody></table><p>この二つは同じ量ではありません。C++の定義は1付近の刻み幅で、C#の定義はゼロの直上の最小値です。<code>.NET</code>の資料にも、<code>Single.Epsilon</code>を一般的な精度の尺度として使わないことや、プラットフォームによる扱いの注意があります。どちらも、名前だけから全域共通の比較予算にはできません。<a href="https://timsong-cpp.github.io/cppwp/n4861/numeric.limits.members#25" target="_blank" rel="noreferrer">N4861: epsilon</a>、<a href="https://learn.microsoft.com/en-us/dotnet/api/system.single.epsilon?view=net-10.0" target="_blank" rel="noreferrer">Microsoft: Single.Epsilon</a></p><h2 id="保存済みの値から、失った差は復元できない" tabindex="-1">保存済みの値から、失った差は復元できない <a class="header-anchor" href="#保存済みの値から、失った差は復元できない" aria-label="Permalink to &quot;保存済みの値から、失った差は復元できない&quot;">​</a></h2><p>binary32の2²⁴付近では、大きい側の隣までの間隔が2です。数学上の16,777,217を最近接偶数で保存すると、16,777,216になります。その後で二つを比べれば、厳密な等値も近似一致も<code>true</code>になり得ます。</p><p>比較側で<code>double</code>に拡張しても、<strong>保存前に失った1という差は戻りません</strong>。1unit＝1mなら、失った情報は1mです。問題が入力の表現や座標の持ち方にある場合、比較の許容差を変更するだけでは解決できません。丸めの具体例は<a href="/study/data/floating-point-spacing.html">刻み幅の記事</a>を参照してください。</p><h2 id="近似一致は推移しない" tabindex="-1">近似一致は推移しない <a class="header-anchor" href="#近似一致は推移しない" aria-label="Permalink to &quot;近似一致は推移しない&quot;">​</a></h2><p>絶対許容差1、相対許容差0で、a＝0、b＝0.75、c＝1.5を考えます。aとbの差、bとcの差はそれぞれ0.75なので受け入れます。しかしaとcの差1.5は受け入れません。<strong>aがbに近く、bがcに近くても、aがcに近いとは限りません。</strong></p><p>これは、等値に期待する推移性を満たさない例です。近似一致をそのままキーの同値関係に使ったり、差が小さければ同順位とする比較器を組み立てたりしてはいけません。C++の並べ替え用の比較には厳密弱順序、ハッシュコンテナのキー比較には同値関係など、別の契約があります。本記事の関数はその代替ではありません。<a href="https://timsong-cpp.github.io/cppwp/n4861/alg.sorting" target="_blank" rel="noreferrer">N4861: ordering requirements</a>、<a href="https://timsong-cpp.github.io/cppwp/n4861/unord.req" target="_blank" rel="noreferrer">unordered container requirements</a></p><figure class="study-figure"><img src="`+r+'" alt="許容差1で0と0.75、0.75と1.5は近いが0と1.5は近くない非推移性の例。floatへの保存時に失った1を比較では復元できないこと、特殊値の方針や到達判定は別に決めることも示す。" width="760" height="1400"><figcaption><strong>「近い」は、数学上の等値や状態遷移の規則をそのまま置き換えない。</strong> 例の値と予算は説明用です。<a href="/study/images/math/comparison-pitfalls.svg" target="_blank" rel="noopener noreferrer">比較の落とし穴の図を拡大</a></figcaption></figure><h2 id="ゲームの到達判定は、目的から別に設計する" tabindex="-1">ゲームの到達判定は、目的から別に設計する <a class="header-anchor" href="#ゲームの到達判定は、目的から別に設計する" aria-label="Permalink to &quot;ゲームの到達判定は、目的から別に設計する&quot;">​</a></h2><p>位置への到達を知りたいなら、「座標の二つの数が近い」だけでなく、<strong>目標までの距離を、許す到達半径と比べる</strong>という仕様を決めます。ワールド座標そのものに相対許容差を掛けると、原点から遠いほど同じ実距離の差を受け入れやすくなります。</p><p>一更新で0→0.75→1.5と進むものは、目標1を通り過ぎても、狭い一致範囲へ一度も入りません。通過を検出する、残り距離を超える移動なら目標にclamp（制限）する、といった動作を設計します。到達後に目標値そのものを代入するなら、その後の厳密な等値にも明確な意味があります。</p><p>境界の前後で状態が頻繁に切り替わるなら、入る距離より出る距離を大きくし、その間では前の状態を保つ<strong>ヒステリシス</strong>が別の設計候補です。許容差を大きくすること、通過への対応、状態を安定させることは、それぞれ目的が異なります。</p><h2 id="用途・単位・値域から選ぶ" tabindex="-1">用途・単位・値域から選ぶ <a class="header-anchor" href="#用途・単位・値域から選ぶ" aria-label="Permalink to &quot;用途・単位・値域から選ぶ&quot;">​</a></h2><p>比較する量と単位、想定する値域、どこまでの差を受け入れるかを先に定めます。ゼロ付近の予算は何unitか、大きな値では何割の差までよいか、境界での判定が状態にどう影響するかを確認します。ここに載せた<code>0.25</code>や<code>1/1024</code>を、そのまま共通定数として採用することはしません。</p><p>コンパイラがNaNや丸めを省略・変更できる設定では、特殊値を含む契約も再確認が必要です。本教材の実践ではMSVCの<code>/fp:strict</code>など、浮動小数点の扱いを確認した条件で観察します。<a href="https://learn.microsoft.com/en-us/cpp/build/reference/fp-specify-floating-point-behavior?view=msvc-170" target="_blank" rel="noreferrer">Microsoft: /fp</a></p><p><a href="/study/practice/math/float-comparison-observation.html">C++とC#で浮動小数点の比較を観察する</a>には、この契約を具体化したサンプルを置きます。表現の土台は<a href="/study/data/floating-point-spacing.html">floatの表現と刻み幅</a>、分野全体の案内は<a href="/study/guide/low-level/computer-and-data.html">情報表現の学習ガイド</a>を参照してください。</p>',52)])])}const f=t(n,[["render",l]]);export{b as __pageData,f as default};
